head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// 발생한 이벤트를 순서대로 기록한다.
scwin.gVar = { log : [] };

scwin.target1_onpanelload = function (panelID, userID) {
    scwin.gVar.log.push("onpanelload (" + userID + ")");
};

scwin.target1_onpanelunload = function (panelID, userID) {
    scwin.gVar.log.push("onpanelunload (" + userID + ")");
};

// 현재 열려 있는 패널 목록을 문자열로 만든다.
scwin.openList = function () {
    var arrInfo = $p.getComponentById("target1").getOpenPanelListInfo();
    if (arrInfo === null || arrInfo.length === 0) { return "없음"; }
    var arrId = [];
    for (var i = 0; i < arrInfo.length; i++) {
        arrId.push(arrInfo[i].id.replace("mf_target1_panel_", ""));
    }
    return arrId.join(", ");
};

// panels1 만 열린 상태를 만든다.
scwin.btn_reset_onclick = function (e) {
    var objTarget = $p.getComponentById("target1");
    objTarget.closePanel("panels1");
    objTarget.closePanel("panels2");
    objTarget.closePanel("panels3");

    setTimeout(function () {
        objTarget.openPanel("panels1");
        setTimeout(function () {
            scwin.gVar.log = [];
            scwin.setReturnValue("=====준비 완료=====");
            scwin.setReturnValue("    열린 패널 : " + scwin.openList());
            scwin.setReturnValue("    (이벤트 기록을 초기화했습니다. 이어서 아래 버튼을 클릭하세요)");
            scwin.setReturnValue("");
        }, 700);
    }, 700);
};

// panels2 를 연다. independentPanel=false 이므로 panels1 이 자동으로 닫힌다.
scwin.btn_open_onclick = function (e) {
    scwin.gVar.log = [];
    $p.getComponentById("target1").openPanel("panels2");

    setTimeout(function () {
        var arrLog = scwin.gVar.log;
        scwin.setReturnValue("=====openPanel('panels2') 실행 결과=====");
        scwin.setReturnValue("    열린 패널 : " + scwin.openList());
        scwin.setReturnValue("    발생한 이벤트 : " + (arrLog.length === 0 ? "없음" : arrLog.join(" / ")));
        scwin.setReturnValue("");

        var bUnload = false;
        for (var i = 0; i < arrLog.length; i++) {
            if (arrLog[i].indexOf("onpanelunload") === 0) { bUnload = true; }
        }
        var bClosed = (scwin.openList().indexOf("panels1") < 0);

        scwin.setReturnValue("----- 판정 -----");
        scwin.setReturnValue("    panels1 자동 닫힘 : " + (bClosed ? "O" : "X"));
        scwin.setReturnValue("    onpanelunload 발생 : " + (bUnload ? "O" : "X"));
        if (bClosed && bUnload) {
            scwin.setReturnValue("배타 모드가 동작해 panels1 이 닫히고 onpanelunload 가 발생했다");
        } else {
            scwin.setReturnValue("배타 모드가 동작하지 않아 panels1 이 열린 채로 남고 onpanelunload 도 발생하지 않았다");
        }
        scwin.setReturnValue("");
    }, 900);
};
